package ai.interviewiq.api.dto;
import ai.interviewiq.api.entity.InterviewStatus; import jakarta.validation.constraints.*; import java.time.Instant; import java.util.*;
public final class InterviewDtos { private InterviewDtos(){} public record CreateRequest(@NotNull @Positive Long companyId,@NotNull @Positive Long jobRoleId,@NotNull @Positive Long difficultyLevelId,@Positive Long interviewTemplateId){} public record QuestionResponse(Long id,int sequenceNumber,String questionText,String questionType,boolean answered){} public record SessionResponse(Long id,CatalogDtos.CompanyResponse company,CatalogDtos.JobRoleResponse jobRole,CatalogDtos.DifficultyResponse difficultyLevel,CatalogDtos.TemplateResponse template,InterviewStatus status,int questionCount,int answeredCount,Instant createdAt,Instant startedAt,Instant completedAt,List<QuestionResponse> questions){} public record AnswerRequest(@NotBlank @Size(max=20000) String answerText,@Pattern(regexp="TYPED|VOICE_TRANSCRIPT") String inputMethod){} public record AnswerResponse(Long questionId,String answerText,String inputMethod,Instant submittedAt){} public record QuestionFeedbackResponse(Long questionId,Double score,List<String> strengths,List<String> improvements,String recommendation){} public record FeedbackResponse(String status,Double overallScore,Double technicalScore,Double communicationScore,Double confidenceScore,String overallAssessment,List<String> strengths,List<String> improvementAreas,List<String> recommendedActions,List<QuestionFeedbackResponse> questionFeedback,Instant generatedAt){} public record PageResponse<T>(List<T> data,String nextCursor,int limit){} }
